// Controlled component records for validator tests; never actual execution proof.
import {mkdir} from 'node:fs/promises';import {join} from 'node:path';import {randomUUID} from 'node:crypto';
import type {PilotHostedScope} from '../../../lib/contracts/pilot-hosted';
import {pilotRunSchema,pilotProofSchema,pilotReceiptSchema} from '../../../lib/contracts/pilot-readiness';
import {pilotCatalog} from '../../../scripts/pilot-catalog';import suites from '../../../scripts/pilot-suites.json';
import {writeEvidence,evidenceDigest} from '../../../scripts/pilot-evidence';
export async function byteComponentFixture(parent:string,scope:PilotHostedScope){
 const directory=join(parent,'component');await mkdir(directory,{mode:0o700});const runId=randomUUID(),environmentMarker='test-pilot-'+randomUUID().replaceAll('-','').slice(0,12),scopeDigest=evidenceDigest(JSON.stringify({runId,method:'local',environmentMarker,inventory:suites})),source={sourceCommit:scope.sourceCommit,sourceDigest:scope.sourceDigest,catalogDigest:scope.catalogDigest},gate=pilotCatalog.gates.find(row=>row.id==='G03')!,attemptId=randomUUID(),receiptIds:string[]=[],receipts=[];
 for(const role of gate.requiredRoles){const id=randomUUID(),binding={runId,attemptId,gateId:gate.id,method:'local',role,workspaceId:scope.workspaceId,...source,environmentMarker,scopeDigest,startedAt:new Date(Date.now()-4000).toISOString(),completedAt:new Date(Date.now()-2000).toISOString(),state:'pass'},proof=pilotProofSchema.parse({version:'pilot-proof-v1',receiptId:id,...binding,cases:gate.localCaseIds.map(id=>({id,state:'pass',flaky:false}))}),proofDigest=await writeEvidence(directory,id+'.json',proof);receipts.push(pilotReceiptSchema.parse({version:'pilot-readiness-v1',id,...binding,expectedCases:proof.cases.length,passedCases:proof.cases.length,failedCases:0,skippedCases:0,flakyCases:0,proofDigest}));receiptIds.push(id);}
 const run=pilotRunSchema.parse({version:'pilot-readiness-v1',id:runId,createdAt:new Date(Date.now()-5000).toISOString(),...source,environmentMarker,scopeDigest,receipts,attempts:[{id:attemptId,gateId:'G03',complete:true,receiptIds}],selectedAttempts:[{gateId:'G03',attemptId}]});await writeEvidence(directory,'run.json',run);
 const file='tests/integration/pilot/generated-byte-boundary.test.ts',index=suites.suites.findIndex(row=>row.file===file),suite=suites.suites[index],result={success:true,numTotalTests:suite.expectedCases,numPassedTests:suite.expectedCases,numFailedTests:0,numPendingTests:0,testResults:[{assertionResults:suite.cases.map(title=>({title,status:'passed'}))}]},resultDigest=await writeEvidence(directory,`suite-${index}.json`,result),processDigest=await writeEvidence(directory,`suite-${index}-process.json`,{file,code:0,signal:null,deadlineExpired:false}),total=suites.suites.reduce((sum,row)=>sum+row.expectedCases,0);
 await writeEvidence(directory,'execution.json',{version:'pilot-execution-v1',state:'pass',method:'local',runId,environmentMarker,...source,expectedCases:total,passedCases:total,suiteEvidenceContract:'pilot-catalog-evidence-index-v1',suiteEvidence:suites.suites.map((row,i)=>({file:row.file,resultFile:`suite-${i}.json`,resultDigest:i===index?resultDigest:'a'.repeat(64),processFile:`suite-${i}-process.json`,processDigest:i===index?processDigest:'b'.repeat(64)}))});return directory;
}
